// 1. System Call: Controlled ECF (User->Kernel Transition)

int fd = 1; // STDOUT_FILENO
const char *message = "Requesting IO\n";
size_t length = 15;

// Syscall wrapper invokes 'trap' instruction
// ECF triggers CPU transition to Ring 0
ssize_t written = write(fd, message, length);

if (written < 0) {
    // Kernel returns control (ECF complete)
    // Error state handled
}

// 2. Synchronous Fault: Uncontrolled ECF (Exception)

volatile int dividend = 100;
volatile int divisor = 0;

// CPU attempts instruction execution
// HW generates Divide-by-Zero fault (trap)
// ECF diverts flow to Kernel Fault Handler
int result = dividend / divisor;

// Execution halted or diverted by OS (e.g., SIGFPE)


// 3. Asynchronous ECF: Handling External Events (Signals)

// Kernel translates hardware interrupt into a signal
void cleanup_handler(int sig) {
    // ECF Response: Context saved, handler executes
    if (sig == SIGTERM) { /* Resource release */ }
}

// Registering the custom ECF path
signal(SIGTERM, cleanup_handler);

// Normal program flow continues until external ECF
while (1) { /* Execution loop */ }
